django ORM 批量更新对象def run(): queryset = HotItem.objects.all() hoitems_to_update = [] for hotitem in queryset: result = classifier(hotitem.title)[0] result = en2zh[result[&quot;label&quot;]] hotitem.category = result hoitems_to_update.append(hotitem) HotItem.objects.bulk_update( hoitems_to_update, [&quot;category&quot;] ) # 第二个参数也是指定要更新的列，这样就不会更新整个对象
逐个 save 是很耗时间的 watch immediate 参数watch( () =&gt; router.currentRoute.value.path, (new_path) =&gt; &#123; const matched = page2category.find((item) =&gt; item.path == new_path); if (matched) &#123; current_category = matched.category; &#125; &#125;, &#123; immediate: true &#125;);
watch 只在监听的变量变化的时候触发，immediate 可以让里面的逻辑在变量初始化的时候也触发一次 路由变换的时候强制刷新有时候，不同 url 指向了同一个组件，导致切换路由的时候没有更新页面，解决方法如下 &lt;router-view :key=&quot;$route.fullPath&quot;&gt;&lt;/router-view&gt;
$router.fullPath 是 vue-router 提供的属性，这段代码的含义是当路由变化的时候会强制刷新组件

后端缓存优化from django.utils.decorators import method_decoratorfrom django.views.decorators.cache import cache_pageclass HotItemView(ListAPIView): serializer_class = HotItemSerializer pagination_class = HotItemPagination @method_decorator(cache_page(60 * 60)) # 缓存 1 小时 def dispatch(self, *args, **kwargs): return super().dispatch(*args, **kwargs) def get_queryset(self): queryset = HotItem.objects.all() source = self.request.GET.get(&quot;source&quot;) category = self.request.query_params.get(&quot;category&quot;) if source: queryset = queryset.filter(source=source) if category: queryset = queryset.filter(category=category) return queryset.order_by(&quot;rank&quot;)
dispatch 是入口函数，通过 request.method 判断应该走 get 还是 post 之类的方法，所以装饰器都应该装到这个函数上面，cache_page 能根据的时间，缓存页面，当参数方法相同的时候，就会返回缓存的页面 render 上面的 key-value 服务对应就是后端的缓存，用的就是 redis cache 配置CACHES = &#123; &quot;default&quot;: &#123; &quot;BACKEND&quot;: &quot;django_redis.cache.RedisCache&quot;, &quot;LOCATION&quot;: os.getenv(&quot;REDIS_URL&quot;), &quot;OPTIONS&quot;: &#123; &quot;CLIENT_CLASS&quot;: &quot;django_redis.client.DefaultClient&quot;, &#125; &#125;&#125;
# 开发环境缓存：本地内存 CACHES = &#123; &quot;default&quot;: &#123; &quot;BACKEND&quot;: &quot;django.core.cache.backends.locmem.LocMemCache&quot;, &#125; &#125;
默认用的本地缓存 post 和 put 这些方法不能用缓存

