django 或查询def get_queryset(self):    queryset = HotItem.objects.all()    source = self.request.GET.get(&quot;source&quot;, None)    categories = self.request.query_params.getlist(        &quot;categories&quot;, None    )  # 列表要用getlist    if source:        queryset = queryset.filter(source=source)  # 不赋值是不会修改queryset的    queryset = queryset.filter(        category__in=categories    )  # 相当于category在categories当中出现的行就会返回    queryset = queryset.order_by(&quot;rank&quot;)    return queryset

