import request from &quot;./request&quot;;export const getHotItems = (source: string, categories?: string[]) =&gt; &#123;  const params = new URLSearchParams();  params.append(&quot;source&quot;, source);  categories?.forEach((c) =&gt; &#123;    params.append(&quot;categories&quot;, c);  &#125;);  // 生成的 URL 例子: hot/?source=哔哩哔哩&amp;categories=文化&amp;categories=财经  return request.get(`hot/?$&#123;params.toString()&#125;`);&#125;;

